void __attribute__((const)) mult_big(uint32_t a, uint32_t b, uint32_t *rem, uint32_t *im){ unsigned int a0 = (a >> 16) &0xffff; unsigned int a1 = a &0xffff; unsigned int a2 = (b >> 16) &0xffff; unsigned int b1 = b &0xffff; unsigned int p0 = a1 * b1; unsigned int p1 = a0 * b1; unsigned int p2 = a1 * a2; unsigned int p3 = a0 * a2; p3 += (p1 >> 16) + (p2 &0xffff); unsigned int p4 = (p2 &0xffff) + (p3 &0xffff); p3 += (p4 >> 16); p0 = (p4 << 16) + (p0 &0xffff); *rem = p3; *im = p0; }